@section('heading', $meus ? 'Meus chamados' : 'Chamados')
@section('content')
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><div class="eyebrow">{{ $meus ? 'Acompanhamento' : 'Operação da manutenção' }}</div><h2 class="h3 mb-1">{{ $meus ? 'Ocorrências que você abriu' : 'Todos os chamados' }}</h2><p class="text-secondary mb-0">{{ $meus ? 'Acompanhe o andamento das suas solicitações.' : 'Visualize e atualize chamados de toda a instituição.' }}</p></div>@if($meus)<a href="{{ route('chamados.create') }}" class="btn btn-primary">＋ Abrir chamado</a>@endif</div>
<div class="panel p-3 mb-3"><div class="row g-2"><div class="col-md-7"><input id="busca" class="form-control" placeholder="Pesquisar pelo título..."></div><div class="col-md-3"><select id="status" class="form-select"><option value="">Todos os status</option><option>Pendente</option><option>Em atendimento</option><option>Resolvido</option></select></div><div class="col-md-2"><button id="filtrar" class="btn btn-primary w-100">Filtrar</button></div></div></div>
<div class="panel overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Número</th><th>Título</th><th>Categoria</th><th>Local</th><th>Prioridade</th><th>Status</th><th>Data</th>@if(!$meus)<th>Atualizar</th>@endif</tr></thead><tbody id="rows"><tr><td colspan="{{ $meus ? 7 : 8 }}" class="text-center text-secondary py-5">Carregando...</td></tr></tbody></table></div></div>
