@section('scripts')
<script>
$(function(){let token=@json(session('api_token')),administrativo=@json(!$meus);function opcoes(status){return ['Pendente','Em atendimento','Resolvido'].map(item=>`<option ${item===status?'selected':''}>${item}</option>`).join('')}function load(){let q=$.param({busca:$('#busca').val(),status:$('#status').val()});$.ajax({url:'/api/chamados?'+q,headers:{Authorization:'Bearer '+token}}).done(function(d){let rows=d.data.map(x=>`<tr><td>#${x.id}</td><td><strong>${x.titulo}</strong><small class="d-block text-secondary">${x.usuario?.name||''}</small></td><td>${x.categoria?.nome||'-'}</td><td>${x.local?.nome||'-'}</td><td><span class="badge" style="background:${x.prioridade?.cor||'#6c757d'}">${x.prioridade?.nome||'-'}</span></td><td>${x.status}</td><td>${new Date(x.data_abertura).toLocaleDateString('pt-BR')}</td>${administrativo?`<td><select class="form-select form-select-sm status-change" data-id="${x.id}" data-old="${x.status}">${opcoes(x.status)}</select></td>`:''}</tr>`).join('');$('#rows').html(rows||`<tr><td colspan="${administrativo?8:7}" class="text-center text-secondary py-5">Nenhum chamado encontrado.</td></tr>`)}).fail(()=>location.href='/login')}load();$('#filtrar').on('click',load);$('#rows').on('change','.status-change',function(){let select=$(this),status=select.val(),old=select.data('old'),id=select.data('id');if(status===old)return;$.ajax({url:'/api/chamados/'+id,method:'PUT',headers:{Authorization:'Bearer '+token},data:{status:status,observacao:'Status atualizado pela equipe de manutenção.'}}).done(function(){Swal.fire({icon:'success',title:'Status atualizado',text:'O chamado agora está como '+status+'.',timer:1800,showConfirmButton:false});load()}).fail(function(){select.val(old);Swal.fire('Não foi possível atualizar','Verifique sua permissão e tente novamente.','error')})})});
</script>
@endsection